    // server/server.js
    require('dotenv').config();
    const express = require('express');
    const mongoose = require('mongoose');
    const cors = require('cors');

    const app = express();
    const PORT = process.env.PORT || 5000;

    // Middleware
    app.use(cors());
    app.use(express.json());

    // MongoDB Connection
    // Replace MONGO_URI with your connection string if using Atlas
    // Example: "mongodb+srv://user:pass@cluster.mongodb.net/dbname"
    // Or use "mongodb://localhost:27017/mydb" for local
    const MONGO_URI = process.env.MONGO_URI || 'mongodb://localhost:27017/fullstackapp';

    mongoose.connect(MONGO_URI)
        .then(() => console.log('MongoDB Connected'))
        .catch(err => console.log(err));

    // Schema & Model
    const ItemSchema = new mongoose.Schema({
        name: String,
        description: String,
        createdAt: { type: Date, default: Date.now }
    });

    const Item = mongoose.model('Item', ItemSchema);

    // Routes

    // 1. Get all items
    app.get('/api/items', async (req, res) => {
        try {
            const items = await Item.find().sort({ createdAt: -1 });
            res.json(items);
        } catch (error) {
            res.status(500).json({ message: error.message });
        }
    });

    // 2. Add a new item
    app.post('/api/items', async (req, res) => {
        const item = new Item({
            name: req.body.name,
            description: req.body.description
        });

        try {
            const newItem = await item.save();
            res.status(201).json(newItem);
        } catch (error) {
            res.status(400).json({ message: error.message });
        }
    });

    // Start Server
    app.listen(PORT, () => {
        console.log(`Server running on port ${PORT}`);
    });
    ```

