To solve this, we need a **global registry** (managed by a Context Provider) that holds the ID of the currently active tooltip.

Here is a complete, copy-pasteable solution using **Next.js (App Router compatible)**, **React Context**, and **Tailwind CSS** for styling.

### 1. The Context Provider (`TooltipContext.tsx`)

This file manages the state of the "active" tooltip. We use a unique ID for every tooltip instance.

```tsx
"use client";

import React, { createContext, useContext, useState, useEffect, ReactNode } from "react";

// 1. Define the shape of our context
interface TooltipContextType {
  activeTooltipId: string | null;
  registerTooltip: (id: string) => void;
  unregisterTooltip: (id: string) => void;
  closeAllTooltips: () => void;
}

const TooltipContext = createContext<TooltipContextType | undefined>(undefined);

// 2. Create the Provider Component
export const TooltipProvider = ({ children }: { children: ReactNode }) => {
  const [activeTooltipId, setActiveTooltipId] = useState<string | null>(null);

  const registerTooltip = (id: string) => {
    setActiveTooltipId(id);
  };

  const unregisterTooltip = (id: string) => {
    // If the tooltip being unregistered is the active one, clear it
    if (activeTooltipId === id) {
      setActiveTooltipId(null);
    }
  };

  const closeAllTooltips = () => {
    setActiveTooltipId(null);
  };

  // Optional: Close tooltips when clicking outside
  useEffect(() => {
    const handleClickOutside = () => closeAllTooltips();
    document.addEventListener("click", handleClickOutside);
    return () => document.removeEventListener("click", handleClickOutside);
  }, []);

  return (
    <TooltipContext.Provider
      value={{ activeTooltipId, registerTooltip, unregisterTooltip, closeAllTooltips }}
    >
      {children}
    </TooltipContext.Provider>
  );
};

// 3. Create a custom hook to use the context easily
export const useTooltipContext = () => {
  const context = useContext(TooltipContext);
  if (!context) {
    throw new Error("useTooltipContext must be used within a TooltipProvider");
  }
  return context;
};
```

